    "kernel_code": "1: import torch\n2: import triton\n3: import triton.language as tl\n4: \n5: \n6: @triton.jit\n7: def _softmax_kernel(OUT, IN, stride_om, stride_im, n_cols, BLOCK: tl.constexpr):\n8:     row = tl.program_id(0)\n9:     in_row = IN + row * stride_im\n10:     out_row = OUT + row * stride_om\n11:     n_full = n_cols // BLOCK\n12: \n13:     row_max = -float(\"inf\")\n14:     for b in range(tl.cdiv(n_cols, BLOCK)):\n15:         cols = b * BLOCK + tl.arange(0, BLOCK)\n16:         x = tl.load(in_row + cols, mask=cols < n_cols, other=-float(\"inf\"))\n17:         row_max = tl.maximum(row_max, tl.max(x, axis=0))\n18: \n19:     denom = 0.0\n20:     for b in range(n_full):\n21:         cols = b * BLOCK + tl.arange(0, BLOCK)\n22:         x = tl.load(in_row + cols, mask=cols < n_cols, other=-float(\"inf\"))\n23:         denom += tl.sum(tl.exp(x - row_max), axis=0)\n24: \n25:     for b in range(tl.cdiv(n_cols, BLOCK)):\n26:         cols = b * BLOCK + tl.arange(0, BLOCK)\n27:         x = tl.load(in_row + cols, mask=cols < n_cols, other=-float(\"inf\"))\n28:         tl.store(out_row + cols, tl.exp(x - row_max) / denom, mask=cols < n_cols)\n29: \n30: \n31: def softmax(x: torch.Tensor, block_size: int = 128) -> torch.Tensor:\n32:     \"\"\"Row-wise softmax of a 2-D float32 tensor.\"\"\"\n33:     n_rows, n_cols = x.shape\n34:     out = torch.empty_like(x)\n35:     _softmax_kernel[(n_rows,)](out, x, out.stride(0), x.stride(0), n_cols, BLOCK=block_size)\n36:     return out",
